// User lookup + greeting formatter — the NullReferenceException minefield.
// This mirrors typescript/05-null-safety: same lesson, C# edition.
// Run from the repo root:
//   dotnet run csharp/05-null-safety-csharp/original.cs
//
// #nullable disable = how ALL C# code worked before 2019, and how many old
// codebases still run: the compiler never asks "could this be null?"
// The refactor flips this switch on — and the compiler finds every landmine.
#nullable disable

var directory = new UserDirectory();

// Path 1: user exists, has an email. Works great. Ship it!
Console.WriteLine(Greeter.Greet(directory, 1));

// Path 2: user exists... but Email is null. No crash — worse, a QUIET bug:
// null glued into a string just vanishes. Read the end of the output line.
Console.WriteLine(Greeter.Greet(directory, 2));

// Path 3: user doesn't exist. FindUser returns null, Greet never checks,
// and user.Name explodes. We catch it here ONLY so you can read the autopsy —
// in real code this is the 500 error page.
Console.WriteLine();
Console.WriteLine("Looking up user 99...");
try
{
    Console.WriteLine(Greeter.Greet(directory, 99));
}
catch (NullReferenceException ex)
{
    Console.WriteLine($"CRASH (caught): {ex.Message}");
    Console.WriteLine("  what happened: FindUser(99) found nothing and returned null.");
    Console.WriteLine("  Greet trusted the result and called user.Name — on null.");
    Console.WriteLine("  JS equivalent: TypeError: Cannot read properties of null (reading 'name')");
}
Console.WriteLine();
Console.WriteLine("App exited cleanly — but only because of the try/catch band-aid above.");

class User
{
    public int Id;
    public string Name;
    public string Email;   // "optional" — but nothing in the type says so

    public User(int id, string name, string email)
    {
        Id = id;
        Name = name;
        Email = email;
    }
}

class UserDirectory
{
    List<User> users = new List<User>
    {
        new User(1, "Ada", "ada@example.com"),
        new User(2, "Grace", null),   // signed up before email was required
    };

    public User FindUser(int id)
    {
        foreach (var user in users)
        {
            if (user.Id == id) return user;
        }
        return null;   // "not found" — a landmine the caller can't see in the type
    }
}

static class Greeter
{
    public static string Greet(UserDirectory directory, int id)
    {
        User user = directory.FindUser(id);   // might be null. Who checks? Nobody.
        return "Hello, " + user.Name.ToUpper() + "! We'll email you at " + user.Email;
    }
}

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

public static class Greeter
{
    // Guard clause first: handle "no user" and get out. After the guard, `user`
    // is guaranteed non-null — no pyramid of ifs around the happy path.
    public static string Greet(UserDirectory directory, int id)
    {
        if (!directory.TryFind(id, out var user))
        {
            return $"Hello, guest! (no user with id {id})";
        }

        // ?? = "if the left side is null, use the right side instead".
        var email = user.Email ?? "no email on file";
        return $"Hello, {user.Name.ToUpper()}! We'll email you at {email}";
    }

    // ?. = "if the thing before me is null, stop and produce null" — the whole
    // chain short-circuits, then ?? supplies the fallback. Handles BOTH
    // "no user" and "user without an email" in one line.
    public static string EmailDomain(User? user) =>
        user?.Email?.Split('@').ElementAtOrDefault(1) ?? "(none)";
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

// Same three lookups as original.cs — no try/catch needed anywhere,
// because no path can throw NullReferenceException anymore.
var directory = UserDirectory.Demo();

Console.WriteLine(Greeter.Greet(directory, 1));   // exists, has email
Console.WriteLine(Greeter.Greet(directory, 2));   // exists, Email is null
Console.WriteLine(Greeter.Greet(directory, 99));  // missing — a normal, handled case

Console.WriteLine();
Console.WriteLine($"Ada's email domain:   {Greeter.EmailDomain(directory.FindOrNull(1))}");
Console.WriteLine($"Grace's email domain: {Greeter.EmailDomain(directory.FindOrNull(2))}");
Console.WriteLine($"user 99's domain:     {Greeter.EmailDomain(directory.FindOrNull(99))}");

public static class Tests
{
    public static int Run()
    {
        var directory = UserDirectory.Demo();

        Console.WriteLine("FindOrNull");
        Check.Equal("Ada", directory.FindOrNull(1)?.Name, "existing user comes back");
        Check.True(directory.FindOrNull(99) is null, "missing user comes back null — not a crash");

        Console.WriteLine("TryFind");
        Check.True(directory.TryFind(1, out var ada), "returns true for an existing user");
        Check.Equal("Ada", ada?.Name, "and hands the user out");
        Check.True(!directory.TryFind(99, out var nobody), "returns false for a missing user");
        Check.True(nobody is null, "and the out value is null");

        Console.WriteLine("Greet — every path returns a string, none can throw");
        Check.Equal("Hello, ADA! We'll email you at ada@example.com",
            Greeter.Greet(directory, 1), "user with email");
        Check.Equal("Hello, GRACE! We'll email you at no email on file",
            Greeter.Greet(directory, 2), "user with null email gets the ?? fallback");
        Check.Equal("Hello, guest! (no user with id 99)",
            Greeter.Greet(directory, 99), "missing user gets the guest greeting");
        Check.Equal("Hello, guest! (no user with id -1)",
            Greeter.Greet(directory, -1), "silly ids are just another miss");

        Console.WriteLine("EmailDomain — ?. chain plus ?? fallback");
        Check.Equal("example.com", Greeter.EmailDomain(directory.FindOrNull(1)), "real email -> its domain");
        Check.Equal("(none)", Greeter.EmailDomain(directory.FindOrNull(2)), "null email -> fallback");
        Check.Equal("(none)", Greeter.EmailDomain(directory.FindOrNull(99)), "null user -> same fallback");
        Check.Equal("(none)", Greeter.EmailDomain(new User(3, "Bo", "not-an-email")), "no @ sign -> fallback");

        Console.WriteLine("Empty directory — edge of the edge");
        var empty = new UserDirectory(new List<User>());
        Check.True(empty.FindOrNull(1) is null, "empty directory finds nobody");
        Check.Equal("Hello, guest! (no user with id 1)", Greeter.Greet(empty, 1),
            "greeting still works with zero users");

        return Check.Summary();
    }
}

// The type now TELLS THE TRUTH:
//   Name  is string  — never null, the compiler enforces it at every call site.
//   Email is string? — explicitly "string or null", so every use must handle null.
public record User(int Id, string Name, string? Email);

using System.Diagnostics.CodeAnalysis;

public class UserDirectory
{
    private readonly List<User> _users;

    public UserDirectory(IEnumerable<User> users) => _users = users.ToList();

    public static UserDirectory Demo() => new(new[]
    {
        new User(1, "Ada", "ada@example.com"),
        new User(2, "Grace", null),   // legal — Email is string?, the type allows it
    });

    // Option A: return User? — "maybe a user". Callers that forget to check
    // get a compiler WARNING at the exact line that would have crashed.
    public User? FindOrNull(int id)
    {
        foreach (var user in _users)
        {
            if (user.Id == id) return user;
        }
        return null;
    }

    // Option B: the TryFind pattern (same shape as Dictionary.TryGetValue).
    // Returns "did it work?" and hands the user out through an `out` parameter.
    // [NotNullWhen(true)] teaches the compiler: "if I returned true, user isn't
    // null" — so `if (TryFind(...))` bodies can use `user` freely.
    public bool TryFind(int id, [NotNullWhen(true)] out User? user)
    {
        user = FindOrNull(id);
        return user is not null;
    }
}
